#!/bin/bash
# SYBNB SR (rides) e2e runner — generated by Claude 2026-10-15.
# Same disposable Neon test DB as run-e2e-auth.sh — NOT production.
set -u
cd "$(dirname "$0")"

export DATABASE_URL="${DATABASE_URL:?set DATABASE_URL in your shell (test DB only)}"
export AUTH_SECRET='e2e-test-auth-secret-0123456789abcdef0123456789abcdef'
export PHONE_HASH_SECRET='e2e-test-phone-hash-secret-0123456789abcdef01234567'
export OTP_EXPOSE_FOR_TEST=true
export SYBNB_COUNTRY=syria
export STORAGE_ALLOW_LOCAL=true
export API_PORT=3051
export API_BASE=http://127.0.0.1:3051

# Fixture ids (same as run-all-e2e.sh) + a dedicated e2e driver
export BUYER=b2cf0295-8b24-4be0-a014-8b9321c44e0a
export GUEST=e14887c6-6fff-4cab-bcea-62e1b976ea61
export GUEST2=ec554c79-c1e4-451a-b65c-206486a5a491
export ADMIN=c6b57605-18aa-4093-bd99-264185de4b26
export DRIVER_ID=d0e2ed1e-0000-4000-8000-000000000001

LOG=e2e-sr-results.log
: > "$LOG"
say() { echo "$@" | tee -a "$LOG"; }

if lsof -iTCP:3051 -sTCP:LISTEN >/dev/null 2>&1; then
  say "ERROR: port 3051 is already in use by:"; lsof -iTCP:3051 -sTCP:LISTEN | tee -a "$LOG"; exit 1
fi

say "== prisma generate (VIP enum) + migrate deploy =="
npx prisma generate >> "$LOG" 2>&1 || { say "PRISMA GENERATE FAILED — see $LOG"; exit 1; }
# Recover from the one failed 066 attempt (TEXT vs uuid, fixed 2026-10-15): mark it rolled back
# if the migrations table says it failed; harmless no-op error otherwise.
npx prisma migrate resolve --rolled-back 066_food_delivery >> "$LOG" 2>&1 || true
npx prisma migrate deploy >> "$LOG" 2>&1 || { say "MIGRATE FAILED — see $LOG"; exit 1; }

say "== seed shared e2e fixtures (fresh DB) =="
node scripts/ci-seed-e2e-fixtures.mjs >> "$LOG" 2>&1 || { say "SEED FAILED — see $LOG"; exit 1; }

say "== seed e2e driver fixture =="
node --input-type=module -e "
import { db, disconnectDb } from './server/lib/prisma.mjs'
const id = process.env.DRIVER_ID
await db().user.upsert({
  where: { id },
  create: { id, email: 'e2e-driver@example.test', displayName: 'E2E Driver Ahmad', locale: 'ar-SY', idDocumentStatus: 'APPROVED' },
  update: { idDocumentStatus: 'APPROVED', status: 'ACTIVE' },
})
await db().userRole.upsert({ where: { userId_role: { userId: id, role: 'DRIVER' } }, create: { userId: id, role: 'DRIVER' }, update: {} })
await db().driverProfile.upsert({
  where: { userId: id },
  create: {
    userId: id, vehicleMake: 'Kia', vehicleModel: 'Rio', vehiclePlate: 'DMS-12345',
    vehicleYear: 2021, vehicleColor: 'White', vehicleCategory: 'ECONOMY',
    vehicleStatus: 'APPROVED', inspectionStatus: 'PASSED', active: true,
  },
  update: { vehicleStatus: 'APPROVED', inspectionStatus: 'PASSED', active: true, vehicleCategory: 'ECONOMY' },
})
console.log('driver fixture ready')
await disconnectDb()
" >> "$LOG" 2>&1 || { say "DRIVER SEED FAILED — see $LOG"; exit 1; }

say "== starting API =="
node server/index.mjs >> api-e2e.log 2>&1 &
API_PID=$!
trap 'kill $API_PID 2>/dev/null' EXIT
for i in $(seq 1 30); do
  curl -s -o /dev/null http://127.0.0.1:3051/api/health && break
  sleep 1
done
curl -s -o /dev/null http://127.0.0.1:3051/api/health || { say "API FAILED TO START — see api-e2e.log"; exit 1; }
say "API up (pid $API_PID)"

OVERALL=0
for s in sr-geocoding sr-vip-bonus sr-ride sr-ride-pooling-discount food-order food-menu-studio food-order-experience; do
  say ""
  say "=============== SUITE: $s ==============="
  node "tests/e2e/$s.e2e.mjs" >> "$LOG" 2>&1
  rc=$?
  [ $rc -ne 0 ] && OVERALL=1
  say "--- exit code: $rc ---"
done

say ""
say "== DONE — overall: $([ $OVERALL -eq 0 ] && echo ALL SR SUITES PASSED || echo SOME SR SUITES FAILED) =="
exit $OVERALL
